import { useId } from 'react'
import type { CatalogService } from '../core/catalogPort'
import type { RuntimeContext } from '../core/runtime'
import type { CatalogProduct } from '../core/catalogTypes'
import { formatPrice } from '../core/catalogFormat'
import { useCatalogController } from './useCatalogController'

/*
 * Markup and styling mirror the blink catalog page
 * (MoleculeProductBlock.vue → MoleculeSearch / MoleculeProductItem /
 * MoleculePagination): block header with a "Showing N results" tag,
 * bordered search bar, horizontal product cards (image · text · attribute
 * fields · action button) and numbered pagination.
 */

/** 'horizontal' (blink's productItemOrientation) stacks full-width cards, image left; 'grid' wraps vertical cards. */
export type CatalogLayout = 'horizontal' | 'grid'

export interface CatalogPanelProps {
  context: RuntimeContext
  service: CatalogService
  onProductSelected?: (product: CatalogProduct) => void
  onAddToCart?: (product: CatalogProduct, quantity: number) => void
  title?: string
  debounceMs?: number
  pageSize?: number
  layout?: CatalogLayout
}

const SearchIcon = () => (
  <svg className="ec-catalog__search-icon" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
    <path
      d="M15.5 14h-.79l-.28-.27a6.5 6.5 0 1 0-.7.7l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0A4.5 4.5 0 1 1 14 9.5 4.5 4.5 0 0 1 9.5 14z"
      fill="currentColor"
    />
  </svg>
)

const ErrorIcon = () => (
  <svg className="ec-catalog__not-found-icon" viewBox="0 0 24 24" width="17" height="17" aria-hidden="true">
    <path
      d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"
      fill="currentColor"
    />
  </svg>
)

const ArrowIcon = ({ direction }: { direction: 'back' | 'forward' }) => (
  <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
    {direction === 'back' ? (
      <path d="M20 11H7.83l5.59-5.59L12 4l-8 8 8 8 1.41-1.41L7.83 13H20v-2z" fill="currentColor" />
    ) : (
      <path d="M12 4l-1.41 1.41L16.17 11H4v2h12.17l-5.58 5.59L12 20l8-8z" fill="currentColor" />
    )}
  </svg>
)

/** Blink MoleculePagination's desktop windowing: up to 7 boxes with '...' gaps. */
function paginationOf(current: number, pages: number): Array<number | '...'> {
  if (pages <= 7) return Array.from({ length: pages }, (_, i) => i + 1)
  if (current <= 4) return [1, 2, 3, 4, '...', pages - 1, pages]
  if (current >= pages - 3) return [1, 2, '...', pages - 3, pages - 2, pages - 1, pages]
  return [1, '...', current - 1, current, current + 1, '...', pages]
}

export function CatalogPanel(props: CatalogPanelProps) {
  const idBase = useId()
  const layout = props.layout ?? 'horizontal'
  const { state, controller } = useCatalogController({
    service: props.service,
    context: props.context,
    onProductSelected: props.onProductSelected,
    onAddToCart: props.onAddToCart,
    debounceMs: props.debounceMs,
    pageSize: props.pageSize,
  })

  const showSkeletons = state.loading && state.products.length === 0
  const noRecords = state.loaded && !state.loading && state.products.length === 0 && !state.degraded

  return (
    <section className="ec-catalog">
      <div className="ec-catalog__header">
        <div className="ec-catalog__header-title">
          <span className="ec-catalog__subheading">
            {state.loaded ? `Showing ${state.totalCount} results` : 'Showing ... results'}
          </span>
          <h3 className="ec-catalog__title">{props.title ?? 'Catalog'}</h3>
        </div>
      </div>

      <div className="ec-catalog__search">
        <div className="ec-catalog__search-box">
          <input
            id={`${idBase}-search`}
            type="search"
            aria-label="Search products"
            placeholder="Search products..."
            autoComplete="off"
            value={state.query}
            onChange={(event) => controller.setQuery(event.target.value)}
          />
          <SearchIcon />
        </div>
      </div>

      {state.errorMessage ? (
        <div role="alert" className="ec-catalog__alert">
          <span>{state.errorMessage}</span>
          {state.degraded ? (
            <button type="button" className="ec-catalog__retry" onClick={() => void controller.refresh()}>
              Retry
            </button>
          ) : null}
        </div>
      ) : null}

      {noRecords ? (
        <div className="ec-catalog__not-found" data-testid="ec-catalog-empty">
          <ErrorIcon />
          <span className="ec-catalog__not-found-text">No results found</span>
        </div>
      ) : (
        <ul className={`ec-catalog__items ec-catalog__items--${layout}`} data-layout={layout}>
          {showSkeletons
            ? Array.from({ length: 3 }, (_, i) => (
                <li key={`skeleton-${i}`} className={`ec-catalog__card ec-catalog__card--${layout}`} aria-hidden="true">
                  <div className="ec-catalog__card-image">
                    <div className="ec-catalog__skeleton ec-catalog__skeleton--image" />
                  </div>
                  <div className="ec-catalog__card-text">
                    <div className="ec-catalog__skeleton ec-catalog__skeleton--title" />
                    <div className="ec-catalog__skeleton ec-catalog__skeleton--line" />
                  </div>
                </li>
              ))
            : state.products.map((product) => (
                <ProductCard
                  key={product.id}
                  product={product}
                  layout={layout}
                  onOpen={() => void controller.selectProduct(product.id)}
                  onAddToCart={() => controller.addToCart(product.id)}
                />
              ))}
        </ul>
      )}

      {state.pageCount > 1 ? (
        <nav className="ec-catalog__pagination-wrap" aria-label="Catalog pages">
          <ul className="ec-catalog__pagination">
            <li>
              <button
                type="button"
                className="ec-catalog__page ec-catalog__page--arrow"
                aria-label="Previous page"
                disabled={state.page <= 1 || state.loading}
                onClick={() => controller.setPage(state.page - 1)}
              >
                <ArrowIcon direction="back" />
              </button>
            </li>
            {paginationOf(state.page, state.pageCount).map((page, index) =>
              page === '...' ? (
                <li key={`gap-${index}`}>
                  <span className="ec-catalog__page ec-catalog__page--gap">…</span>
                </li>
              ) : (
                <li key={page}>
                  <button
                    type="button"
                    className="ec-catalog__page"
                    aria-label={`Go to page ${page}`}
                    aria-current={state.page === page ? 'page' : undefined}
                    disabled={state.loading}
                    onClick={() => controller.setPage(page)}
                  >
                    {page}
                  </button>
                </li>
              ),
            )}
            <li>
              <button
                type="button"
                className="ec-catalog__page ec-catalog__page--arrow"
                aria-label="Next page"
                disabled={state.page >= state.pageCount || state.loading}
                onClick={() => controller.setPage(state.page + 1)}
              >
                <ArrowIcon direction="forward" />
              </button>
            </li>
          </ul>
        </nav>
      ) : null}
    </section>
  )
}

interface ProductCardProps {
  product: CatalogProduct
  layout: CatalogLayout
  onOpen: () => void
  onAddToCart: () => void
}

function ProductCard({ product, layout, onOpen, onAddToCart }: ProductCardProps) {
  return (
    <li className={`ec-catalog__card ec-catalog__card--${layout}`} data-in-stock={product.inStock}>
      <div className="ec-catalog__card-image">
        {product.imageUrl ? (
          <img src={product.imageUrl} alt="" loading="lazy" />
        ) : (
          <div className="ec-catalog__card-image-placeholder">{product.sku}</div>
        )}
      </div>
      <div className="ec-catalog__card-text">
        <button type="button" className="ec-catalog__card-title" onClick={onOpen}>
          {product.name}
        </button>
        <p className="ec-catalog__card-desc">{product.description}</p>
      </div>
      <div className="ec-catalog__card-attributes">
        <div className="ec-catalog__card-field">
          <span className="ec-catalog__card-field-label">SKU</span>
          <span className="ec-catalog__card-field-value">{product.sku}</span>
        </div>
        <div className="ec-catalog__card-field">
          <span className="ec-catalog__card-field-label">Price</span>
          <span className="ec-catalog__card-field-value">{formatPrice(product.price, product.currency)}</span>
        </div>
      </div>
      <div className="ec-catalog__card-button">
        {product.inStock ? (
          <button type="button" className="ec-catalog__btn-primary" onClick={onAddToCart}>
            Add to cart
          </button>
        ) : (
          <span className="ec-catalog__not-available">Not Available</span>
        )}
      </div>
    </li>
  )
}
