import type { AddressService } from '../core/port'
import type {
  ListSavedAddressesResult,
  ResolveAddressResult,
  SearchAddressesResult,
  ValidateAddressResult,
} from '../core/types'

/**
 * The composable-core transport seam (Foundry-30845): a generic
 * Executor(method, payload). The host's runtime factory supplies a mock,
 * custom (BFF), or lwc implementation — this package never talks to a
 * network or to Salesforce directly. Google Places stays behind the host
 * BFF (POST /api/v1/platform/address:search); no vendor SDK is embedded.
 */
export type ComposableExecutor = (method: string, payload: Record<string, unknown>) => Promise<unknown>

export const ADDRESS_EXECUTOR_METHODS = {
  searchAddresses: 'platform/address:search',
  resolveAddress: 'platform/address:resolve',
  validateAddress: 'platform/address:validate',
  listSavedAddresses: 'platform/address:listSaved',
} as const

const errorMessageOf = (error: unknown): string =>
  error instanceof Error ? error.message : 'Address service request failed'

/** Wraps an executor as an AddressService. Executor failures become `{ status: 'error' }` — never a rejection. */
export function createExecutorAddressService(executor: ComposableExecutor): AddressService {
  return {
    async searchAddresses(context, input) {
      try {
        return (await executor(ADDRESS_EXECUTOR_METHODS.searchAddresses, { context, ...input })) as SearchAddressesResult
      } catch (error) {
        return { status: 'error', errorMessage: errorMessageOf(error), suggestions: [] }
      }
    },
    async resolveAddress(context, input) {
      try {
        return (await executor(ADDRESS_EXECUTOR_METHODS.resolveAddress, { context, ...input })) as ResolveAddressResult
      } catch (error) {
        return { status: 'error', errorMessage: errorMessageOf(error) }
      }
    },
    async validateAddress(context, input) {
      try {
        return (await executor(ADDRESS_EXECUTOR_METHODS.validateAddress, { context, ...input })) as ValidateAddressResult
      } catch (error) {
        return { status: 'error', errorMessage: errorMessageOf(error) }
      }
    },
    async listSavedAddresses(context, input) {
      try {
        return (await executor(ADDRESS_EXECUTOR_METHODS.listSavedAddresses, { context, ...input })) as ListSavedAddressesResult
      } catch (error) {
        return { status: 'error', errorMessage: errorMessageOf(error), addresses: [] }
      }
    },
  }
}
