import type { RuntimeContext } from '../core/runtime'
import type { AddressDTO, AddressSuggestion, SavedAddress } from '../core/types'
import { normalizeAddress, validateAddressFormat } from '../core/validation'

export interface MockAddressFixture {
  suggestion: AddressSuggestion
  address: AddressDTO
}

const DEFAULT_FIXTURES: MockAddressFixture[] = [
  {
    suggestion: { id: 'sugg-austin', label: '600 Congress Ave, Austin, TX 78701, USA' },
    address: { street: '600 Congress Ave', city: 'Austin', state: 'TX', zip: '78701', country: 'US' },
  },
  {
    suggestion: { id: 'sugg-sf', label: '1 Market St, San Francisco, CA 94105, USA' },
    address: { street: '1 Market St', city: 'San Francisco', state: 'CA', zip: '94105', country: 'US' },
  },
  {
    suggestion: { id: 'sugg-toronto', label: '325 Front St W, Toronto, ON M5V 2Y1, Canada' },
    address: { street: '325 Front St W', city: 'Toronto', state: 'ON', zip: 'M5V 2Y1', country: 'CA' },
  },
  {
    suggestion: { id: 'sugg-vancouver', label: '800 Robson St, Vancouver, BC V6Z 2E7, Canada' },
    address: { street: '800 Robson St', city: 'Vancouver', state: 'BC', zip: 'V6Z 2E7', country: 'CA' },
  },
]

const DEFAULT_SAVED: SavedAddress[] = [
  {
    id: 'saved-hq',
    label: 'Head office',
    address: { street: '600 Congress Ave', city: 'Austin', state: 'TX', zip: '78701', country: 'US' },
  },
  {
    id: 'saved-warehouse',
    label: 'Warehouse',
    address: { street: '2100 Logistics Pkwy', city: 'Dallas', state: 'TX', zip: '75201', country: 'US' },
  },
]

export interface MockAddressServiceOptions {
  latencyMs?: number
  failSearch?: boolean
  failResolve?: boolean
  failValidate?: boolean
  fixtures?: MockAddressFixture[]
  savedAddresses?: SavedAddress[]
}

/**
 * Complete in-memory AddressService — lets a consumer checkout run e2e with
 * no backend (mock-first rule). Failure flags simulate provider outages so
 * hosts can exercise the manual-entry fallback deterministically.
 */
export function createMockAddressService(options: MockAddressServiceOptions = {}): AddressService {
  const fixtures = options.fixtures ?? DEFAULT_FIXTURES
  const saved = options.savedAddresses ?? DEFAULT_SAVED
  const wait = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, options.latencyMs ?? 0))

  return {
    async searchAddresses(_context, input) {
      await wait()
      if (options.failSearch) return { status: 'error', errorMessage: 'mock: address search unavailable', suggestions: [] }
      const text = input.text.toLowerCase()
      return {
        status: 'success',
        suggestions: fixtures
          .filter((fixture) => fixture.suggestion.label.toLowerCase().includes(text))
          .map((fixture) => fixture.suggestion),
      }
    },

    async resolveAddress(_context, input) {
      await wait()
      if (options.failResolve) return { status: 'error', errorMessage: 'mock: address resolve unavailable' }
      const fixture = fixtures.find((entry) => entry.suggestion.id === input.suggestionId)
      if (!fixture) return { status: 'error', errorMessage: `mock: unknown suggestion ${input.suggestionId}` }
      return { status: 'success', address: fixture.address }
    },

    async validateAddress(_context, input) {
      await wait()
      if (options.failValidate) return { status: 'error', errorMessage: 'mock: address validation unavailable' }
      const issues = validateAddressFormat(input.address, input.addressType)
      if (Object.keys(issues).length > 0) {
        return { status: 'success', valid: false, issues, errorMessage: 'This address could not be verified' }
      }
      return { status: 'success', valid: true, normalized: normalizeAddress(input.address) }
    },

    async listSavedAddresses(context, _input) {
      await wait()
      if (!context.identity.accountId) return { status: 'success', addresses: [] }
      return { status: 'success', addresses: saved }
    },
  }
}

/** Convenience RuntimeContext for demos and tests. */
export function createMockRuntimeContext(overrides: Partial<RuntimeContext> = {}): RuntimeContext {
  return {
    runtime: 'mock',
    identity: { organizationId: 'org-mock', accountId: 'acct-mock', ...overrides.identity },
    session: { origin: 'REACT_STOREFRONT', quoteId: 'quote-mock', ...overrides.session },
    ...(overrides.security ? { security: overrides.security } : {}),
    ...(overrides.runtime ? { runtime: overrides.runtime } : {}),
  }
}
