const sortProducts = (products: CatalogProduct[], sort: CatalogSort): CatalogProduct[] => {
  const sorted = [...products]
  switch (sort) {
    case 'price-asc':
      return sorted.sort((a, b) => a.price - b.price)
    case 'price-desc':
      return sorted.sort((a, b) => b.price - a.price)
    case 'name':
      return sorted.sort((a, b) => a.name.localeCompare(b.name))
    case 'relevance':
      return sorted // fixture order stands in for provider ranking
  }
}

export interface MockCatalogServiceOptions {
  latencyMs?: number
  failSearch?: boolean
  failGetProduct?: boolean
  failCategories?: boolean
  products?: CatalogProduct[]
  categories?: CatalogCategory[]
}

/**
 * Complete in-memory CatalogService — lets a consumer catalog page run e2e
 * with no backend (mock-first rule). Failure flags simulate provider outages
 * so hosts can exercise the degraded-but-browsable state deterministically.
 */
export function createMockCatalogService(options: MockCatalogServiceOptions = {}): CatalogService {
  const products = options.products ?? DEFAULT_PRODUCTS
  const categories = options.categories ?? DEFAULT_CATEGORIES
  const wait = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, options.latencyMs ?? 0))

  return {
    async searchProducts(_context, input) {
      await wait()
      if (options.failSearch) {
        return { status: 'error', errorMessage: 'mock: catalog search unavailable', products: [], totalCount: 0 }
      }
      const text = input.text.trim().toLowerCase()
      const matches = sortProducts(
        products.filter((product) => {
          if (input.categoryId && product.categoryId !== input.categoryId) return false
          if (!text) return true
          return [product.name, product.description, product.sku].some((field) =>
            field.toLowerCase().includes(text),
          )
        }),
        input.sort,
      )
      const start = (input.page - 1) * input.pageSize
      return {
        status: 'success',
        products: matches.slice(start, start + input.pageSize),
        totalCount: matches.length,
      }
    },

    async getProduct(_context, input) {
      await wait()
      if (options.failGetProduct) return { status: 'error', errorMessage: 'mock: product lookup unavailable' }
      const product = products.find((entry) => entry.id === input.productId)
      if (!product) return { status: 'error', errorMessage: `mock: unknown product ${input.productId}` }
      return { status: 'success', product }
    },

    async listCategories(_context) {
      await wait()
      if (options.failCategories) return { status: 'error', errorMessage: 'mock: categories unavailable', categories: [] }
      return { status: 'success', categories }
    },
  }
}
