import { useEffect, useRef, useSyncExternalStore } from 'react'
import { createAddressController } from '../ui-logic/addressController'
import type {
  AddressController,
  AddressControllerOptions,
  AddressControllerState,
} from '../ui-logic/addressController'

export interface UseAddressControllerResult {
  state: AddressControllerState
  controller: AddressController
}

/**
 * Binds an AddressController to React. The controller is created once per
 * mount; callbacks are kept fresh across renders via setCallbacks.
 */
export function useAddressController(options: AddressControllerOptions): UseAddressControllerResult {
  const controllerRef = useRef<AddressController | null>(null)
  controllerRef.current ??= createAddressController(options)
  const controller = controllerRef.current

  const { onAddressSelected, onAddressChange } = options
  useEffect(() => {
    controller.setCallbacks({ onAddressSelected, onAddressChange })
  }, [controller, onAddressSelected, onAddressChange])

  useEffect(() => {
    void controller.init()
    return () => {
      controller.dispose()
    }
  }, [controller])

  const state = useSyncExternalStore(controller.subscribe, controller.getState, controller.getState)
  return { state, controller }
}
