import type { CatalogService } from '../core/catalogPort'
import type { RuntimeContext } from '../core/runtime'
import type {
  CatalogCategory,
  CatalogProduct,
  CatalogSort,
} from '../core/catalogTypes'
import type { MutationResult } from '../core/types'
import { DEFAULT_CATALOG_PAGE_SIZE, pageCountOf } from '../core/catalogFormat'

export interface CatalogControllerState {
  query: string
  categoryId: string | null
  sort: CatalogSort
  /** 1-based. */
  page: number
  pageSize: number
  loading: boolean
  /** True once the first search has settled — gates the "no results" state. */
  loaded: boolean
  products: CatalogProduct[]
  totalCount: number
  pageCount: number
  categories: CatalogCategory[]
  loadingCategories: boolean
  /**
   * True while the catalog provider is failing. The last successful page
   * stays on screen — an outage degrades browsing, it never empties the page.
   */
  degraded: boolean
  selected: CatalogProduct | null
  resolvingProductId: string | null
  errorMessage: string | null
}

export interface CatalogControllerCallbacks {
  /** A product was opened/selected (detail view, quote line, …). */
  onProductSelected?: (product: CatalogProduct) => void
  /** Host owns the cart — the composable only emits the DTO + quantity. */
  onAddToCart?: (product: CatalogProduct, quantity: number) => void
}

export interface CatalogControllerOptions extends CatalogControllerCallbacks {
  service: CatalogService
  context: RuntimeContext
  debounceMs?: number
  pageSize?: number
}

export interface CatalogController {
  getState(): CatalogControllerState
  subscribe(listener: () => void): () => void
  setCallbacks(callbacks: CatalogControllerCallbacks): void
  /** Loads category facets and the first page. */
  init(): Promise<void>
  setQuery(text: string): void
  setCategory(categoryId: string | null): void
  setSort(sort: CatalogSort): void
  setPage(page: number): void
  /** Re-runs the current query — the retry path after an outage. */
  refresh(): Promise<void>
  selectProduct(productId: string): Promise<MutationResult>
  addToCart(productId: string, quantity?: number): MutationResult
  dispose(): void
}

const initialState = (pageSize: number): CatalogControllerState => ({
  query: '',
  categoryId: null,
  sort: 'relevance',
  page: 1,
  pageSize,
  loading: false,
  loaded: false,
  products: [],
  totalCount: 0,
  pageCount: 0,
  categories: [],
  loadingCategories: false,
  degraded: false,
  selected: null,
  resolvingProductId: null,
  errorMessage: null,
})

export function createCatalogController(options: CatalogControllerOptions): CatalogController {
  const { service, context } = options
  const debounceMs = options.debounceMs ?? 250
  let callbacks: CatalogControllerCallbacks = {
    onProductSelected: options.onProductSelected,
    onAddToCart: options.onAddToCart,
  }

  let state = initialState(options.pageSize ?? DEFAULT_CATALOG_PAGE_SIZE)
  const listeners = new Set<() => void>()
  let searchTimer: ReturnType<typeof setTimeout> | null = null
  let searchSeq = 0

  const setState = (patch: Partial<CatalogControllerState>): void => {
    state = { ...state, ...patch }
    for (const listener of listeners) listener()
  }

  const runSearch = async (): Promise<void> => {
    const seq = ++searchSeq
    setState({ loading: true })
    const result = await service.searchProducts(context, {
      text: state.query.trim(),
      sort: state.sort,
      page: state.page,
      pageSize: state.pageSize,
      ...(state.categoryId ? { categoryId: state.categoryId } : {}),
    })
    if (seq !== searchSeq) return
    if (result.status === 'error') {
      // Keep the last successful page on screen — an outage never empties the catalog.
      setState({
        loading: false,
        loaded: true,
        degraded: true,
        errorMessage: result.errorMessage ?? 'The catalog is temporarily unavailable — try again.',
      })
      return
    }
    setState({
      loading: false,
      loaded: true,
      degraded: false,
      errorMessage: null,
      products: result.products,
      totalCount: result.totalCount,
      pageCount: pageCountOf(result.totalCount, state.pageSize),
    })
  }

  /** Filter changes restart at page 1 and re-query immediately. */
  const applyFilter = (patch: Partial<CatalogControllerState>): void => {
    if (searchTimer) clearTimeout(searchTimer)
    setState({ ...patch, page: 1 })
    void runSearch()
  }

  return {
    getState: () => state,

    subscribe(listener) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },

    setCallbacks(next) {
      callbacks = next
    },

    async init() {
      setState({ loadingCategories: true })
      const [categoriesResult] = await Promise.all([service.listCategories(context), runSearch()])
      setState({
        loadingCategories: false,
        categories: categoriesResult.status === 'success' ? categoriesResult.categories : [],
      })
    },

    setQuery(text) {
      setState({ query: text, page: 1 })
      if (searchTimer) clearTimeout(searchTimer)
      searchTimer = setTimeout(() => {
        void runSearch()
      }, debounceMs)
    },

    setCategory(categoryId) {
      applyFilter({ categoryId })
    },

    setSort(sort) {
      applyFilter({ sort })
    },

    setPage(page) {
      const clamped = Math.min(Math.max(1, page), Math.max(1, state.pageCount))
      if (clamped === state.page) return
      if (searchTimer) clearTimeout(searchTimer)
      setState({ page: clamped })
      void runSearch()
    },

    async refresh() {
      if (searchTimer) clearTimeout(searchTimer)
      await runSearch()
    },

    async selectProduct(productId) {
      const commit = (product: CatalogProduct): MutationResult => {
        setState({ selected: product })
        callbacks.onProductSelected?.(product)
        return { status: 'success' }
      }
      const local = state.products.find((product) => product.id === productId)
      if (local) return commit(local)
      setState({ resolvingProductId: productId })
      const result = await service.getProduct(context, { productId })
      setState({ resolvingProductId: null })
      if (result.status === 'error' || !result.product) {
        const errorMessage = result.errorMessage ?? 'Could not load that product.'
        setState({ errorMessage })
        return { status: 'error', errorMessage }
      }
      return commit(result.product)
    },

    addToCart(productId, quantity = 1) {
      const product =
        state.products.find((entry) => entry.id === productId) ??
        (state.selected?.id === productId ? state.selected : undefined)
      if (!product) return { status: 'error', errorMessage: 'Product not found' }
      if (!product.inStock) return { status: 'error', errorMessage: 'This product is out of stock' }
      if (quantity < 1) return { status: 'error', errorMessage: 'Quantity must be at least 1' }
      callbacks.onAddToCart?.(product, quantity)
      return { status: 'success' }
    },

    dispose() {
      if (searchTimer) clearTimeout(searchTimer)
    },
  }
}
