import { useId, useState } from 'react'
import type { AddressService } from '../core/port'
import type { RuntimeContext } from '../core/runtime'
import type { AddressDTO, AddressField, AddressType } from '../core/types'
import { formatAddressLine } from '../core/validation'
import { useAddressController } from './useAddressController'

const TYPE_TITLES: Record<AddressType, string> = {
  shipping: 'Shipping address',
  billing: 'Billing address',
  install: 'Install address',
}

/* Field labels mirror the blink checkout guest form (CheckoutShippingAddress.vue) */
const FIELD_LABELS: Record<AddressField, string> = {
  street: 'Address Line 1',
  city: 'City',
  state: 'State/Province',
  zip: 'ZIP/Postal Code',
  country: 'Country',
}

const ROW_FIELDS: AddressField[] = ['city', 'state', 'zip', 'country']

const Chevron = ({ expanded }: { expanded: boolean }) => (
  <svg
    className="ec-address__chevron"
    viewBox="0 0 24 24"
    width="24"
    height="24"
    aria-hidden="true"
    style={{ transform: expanded ? 'none' : 'rotate(180deg)' }}
  >
    <path d="M7.41 8.59 12 13.17l4.59-4.58L18 10l-6 6-6-6z" fill="currentColor" />
  </svg>
)

export interface AddressPanelProps {
  context: RuntimeContext
  service: AddressService
  addressType: AddressType
  onAddressSelected?: (address: AddressDTO) => void
  onAddressChange?: (address: AddressDTO) => void
  title?: string
  debounceMs?: number
  minQueryLength?: number
  /** Accordion control (host-driven, like checkout.vue's expand map). Uncontrolled + open by default. */
  expanded?: boolean
  onExpandChange?: (expanded: boolean) => void
}

export function AddressPanel(props: AddressPanelProps) {
  const idBase = useId()
  const [internalExpanded, setInternalExpanded] = useState(true)
  const expanded = props.expanded ?? internalExpanded

  const { state, controller } = useAddressController({
    service: props.service,
    context: props.context,
    addressType: props.addressType,
    onAddressSelected: props.onAddressSelected,
    onAddressChange: props.onAddressChange,
    debounceMs: props.debounceMs,
    minQueryLength: props.minQueryLength,
  })

  const title = props.title ?? TYPE_TITLES[props.addressType]

  /* Header summary fallback chain, like checkout.vue getSelectedAddress */
  const headerSummary = state.selected
    ? state.selected.street || state.selected.city || state.selected.state
    : ''

  const toggle = () => {
    const next = !expanded
    setInternalExpanded(next)
    props.onExpandChange?.(next)
  }

  return (
    <section className="ec-address" data-address-type={props.addressType}>
      <div className="ec-address__section">
        <div
          className="ec-address__header"
          data-expanded={expanded}
          role="button"
          tabIndex={0}
          onClick={toggle}
          onKeyDown={(event) => {
            if (event.key === 'Enter' || event.key === ' ') {
              event.preventDefault()
              toggle()
            }
          }}
        >
          <h3 className="ec-address__title">{title}</h3>
          <div className="ec-address__header-meta">
            {headerSummary ? <span className="ec-address__selectedtext">{headerSummary}</span> : null}
            <Chevron expanded={expanded} />
          </div>
        </div>

        {expanded ? (
          <div className="ec-address__body">
            {state.errorMessage ? (
              <div role="alert" className="ec-address__alert">
                <span>{state.errorMessage}</span>
              </div>
            ) : null}

            {state.selected ? (
              <div className="ec-address__radio-box" data-testid="ec-address-selected">
                <p className="ec-address__radio-box-detail">{formatAddressLine(state.selected)}</p>
              </div>
            ) : null}

            {state.savedAddresses.length > 0 && !state.selected ? (
              <div className="ec-address__saved">
                {state.savedAddresses.map((saved) => (
                  <button
                    key={saved.id}
                    type="button"
                    className="ec-address__radio-box ec-address__radio-box--clickable"
                    onClick={() => controller.selectSavedAddress(saved.id)}
                  >
                    <p className="ec-address__radio-box-title">{saved.label}</p>
                    <p className="ec-address__radio-box-detail">{formatAddressLine(saved.address)}</p>
                  </button>
                ))}
              </div>
            ) : null}

            {state.mode === 'search' && !state.searchDegraded ? (
              <div className="ec-address__search">
                <div className="ec-address__field">
                  <label htmlFor={`${idBase}-search`}>Search for an address</label>
                  <div className="ec-address__input-wrapper">
                    <input
                      id={`${idBase}-search`}
                      className="ec-address__input"
                      type="text"
                      autoComplete="off"
                      placeholder="Start typing an address…"
                      value={state.query}
                      onChange={(event) => controller.setQuery(event.target.value)}
                    />
                  </div>
                </div>
                {state.searching ? <p className="ec-address__hint">Searching…</p> : null}
                {state.suggestions.length > 0 ? (
                  <ul className="ec-address__suggestions">
                    {state.suggestions.map((suggestion) => (
                      <li key={suggestion.id}>
                        <button
                          type="button"
                          className="ec-address__suggestion"
                          disabled={state.resolvingSuggestionId !== null}
                          onClick={() => void controller.selectSuggestion(suggestion.id)}
                        >
                          {suggestion.label}
                        </button>
                      </li>
                    ))}
                  </ul>
                ) : null}
                <button type="button" className="ec-address__link" onClick={() => controller.setMode('manual')}>
                  Enter address manually
                </button>
              </div>
            ) : (
              <form
                className="ec-address__form"
                noValidate
                onSubmit={(event) => {
                  event.preventDefault()
                  void controller.submitManualAddress()
                }}
              >
                <Field
                  field="street"
                  idBase={idBase}
                  value={state.draft.street}
                  error={state.issues.street}
                  onChange={(value) => controller.setDraftField('street', value)}
                />
                <div className="ec-address__row">
                  {ROW_FIELDS.map((field) => (
                    <Field
                      key={field}
                      field={field}
                      idBase={idBase}
                      value={state.draft[field]}
                      error={state.issues[field]}
                      onChange={(value) => controller.setDraftField(field, value)}
                      grow
                    />
                  ))}
                </div>
                <div className="ec-address__actions">
                  {!state.searchDegraded ? (
                    <button type="button" className="ec-address__link" onClick={() => controller.setMode('search')}>
                      Back to search
                    </button>
                  ) : (
                    <span />
                  )}
                  <button type="submit" className="ec-address__btn-primary" disabled={state.submitting}>
                    {state.submitting ? 'Validating…' : 'Continue'}
                  </button>
                </div>
              </form>
            )}
          </div>
        ) : null}
      </div>
    </section>
  )
}

interface FieldProps {
  field: AddressField
  idBase: string
  value: string
  error?: string
  grow?: boolean
  onChange: (value: string) => void
}

function Field({ field, idBase, value, error, grow, onChange }: FieldProps) {
  return (
    <div className={`ec-address__field${grow ? ' ec-address__field--grow' : ''}`}>
      <label htmlFor={`${idBase}-${field}`}>{FIELD_LABELS[field]}</label>
      <div className="ec-address__input-wrapper">
        <input
          id={`${idBase}-${field}`}
          className="ec-address__input"
          type="text"
          autoComplete="off"
          value={value}
          aria-invalid={error ? true : undefined}
          onChange={(event) => onChange(event.target.value)}
        />
      </div>
      {error ? <div className="ec-address__error-tooltip">{error}</div> : null}
    </div>
  )
}
