import type { AddressDTO, AddressType, FieldIssues } from './types'

const US_ZIP = /^\d{5}(-\d{4})?$/
const CA_POSTAL = /^[A-Za-z]\d[A-Za-z][ -]?\d[A-Za-z]\d$/

const US_ALIASES = new Set(['us', 'usa', 'united states', 'united states of america'])
const CA_ALIASES = new Set(['ca', 'can', 'canada'])

export const emptyAddress = (): AddressDTO => ({
  street: '',
  city: '',
  state: '',
  zip: '',
  country: '',
})

/** Collapse common country spellings to ISO-ish codes; pass anything else through. */
export function normalizeCountry(country: string): string {
  const key = country.trim().toLowerCase()
  if (US_ALIASES.has(key)) return 'US'
  if (CA_ALIASES.has(key)) return 'CA'
  return country.trim()
}

/**
 * Offline format validation — the deterministic fallback when the address
 * provider is unavailable. US and Canada get postal-format checks (Homewater
 * sells in both); other countries get presence checks only. Install addresses
 * are strictest: a truck goes to this door, so state/province is always required.
 */
export function validateAddressFormat(address: AddressDTO, addressType: AddressType): FieldIssues {
  const issues: FieldIssues = {}
  const country = normalizeCountry(address.country)

  if (!address.street.trim()) issues.street = 'Street is required'
  if (!address.city.trim()) issues.city = 'City is required'
  if (!address.country.trim()) issues.country = 'Country is required'

  if (country === 'US') {
    if (!address.state.trim()) issues.state = 'State is required'
    if (!US_ZIP.test(address.zip.trim())) issues.zip = 'Enter a valid US ZIP code (12345 or 12345-6789)'
  } else if (country === 'CA') {
    if (!address.state.trim()) issues.state = 'Province is required'
    if (!CA_POSTAL.test(address.zip.trim())) issues.zip = 'Enter a valid Canadian postal code (A1A 1A1)'
  } else {
    if (!address.zip.trim()) issues.zip = 'ZIP / postal code is required'
    if (addressType === 'install' && !address.state.trim()) issues.state = 'State / province is required'
  }

  return issues
}

/** Trim fields, uppercase short state codes and Canadian postal codes. */
export function normalizeAddress(address: AddressDTO): AddressDTO {
  const country = normalizeCountry(address.country)
  const rawState = address.state.trim()
  return {
    street: address.street.trim(),
    city: address.city.trim(),
    state: rawState.length <= 3 ? rawState.toUpperCase() : rawState,
    zip: country === 'CA' ? address.zip.trim().toUpperCase() : address.zip.trim(),
    country,
  }
}

/** Single-line display form, skipping empty parts. */
export function formatAddressLine(address: AddressDTO): string {
  const region = [address.state, address.zip].filter((part) => part.trim() !== '').join(' ')
  return [address.street, address.city, region, address.country]
    .map((part) => part.trim())
    .filter((part) => part !== '')
    .join(', ')
}
