import { useEffect, useRef, useSyncExternalStore } from 'react'
import { createCatalogController } from '../ui-logic/catalogController'
import type {
  CatalogController,
  CatalogControllerOptions,
  CatalogControllerState,
} from '../ui-logic/catalogController'

export interface UseCatalogControllerResult {
  state: CatalogControllerState
  controller: CatalogController
}

/**
 * Binds a CatalogController to React. The controller is created once per
 * mount; callbacks are kept fresh across renders via setCallbacks.
 */
export function useCatalogController(options: CatalogControllerOptions): UseCatalogControllerResult {
  const controllerRef = useRef<CatalogController | null>(null)
  controllerRef.current ??= createCatalogController(options)
  const controller = controllerRef.current

  const { onProductSelected, onAddToCart } = options
  useEffect(() => {
    controller.setCallbacks({ onProductSelected, onAddToCart })
  }, [controller, onProductSelected, onAddToCart])

  useEffect(() => {
    void controller.init()
    return () => {
      controller.dispose()
    }
  }, [controller])

  const state = useSyncExternalStore(controller.subscribe, controller.getState, controller.getState)
  return { state, controller }
}
