import type { AddressService } from '../core/port'
import type { RuntimeContext } from '../core/runtime'
import type {
  AddressDTO,
  AddressField,
  AddressSuggestion,
  AddressType,
  FieldIssues,
  MutationResult,
  SavedAddress,
} from '../core/types'
import { emptyAddress, normalizeAddress, validateAddressFormat } from '../core/validation'

export type AddressEntryMode = 'search' | 'manual'

export interface AddressControllerState {
  mode: AddressEntryMode
  query: string
  searching: boolean
  suggestions: AddressSuggestion[]
  /** True once the search/validation provider has failed — manual entry takes over. */
  searchDegraded: boolean
  savedAddresses: SavedAddress[]
  loadingSaved: boolean
  draft: AddressDTO
  issues: FieldIssues
  submitting: boolean
  resolvingSuggestionId: string | null
  selected: AddressDTO | null
  errorMessage: string | null
}

export interface AddressControllerCallbacks {
  onAddressSelected?: (address: AddressDTO) => void
  onAddressChange?: (address: AddressDTO) => void
}

export interface AddressControllerOptions extends AddressControllerCallbacks {
  service: AddressService
  context: RuntimeContext
  addressType: AddressType
  debounceMs?: number
  minQueryLength?: number
}

export interface AddressController {
  getState(): AddressControllerState
  subscribe(listener: () => void): () => void
  setCallbacks(callbacks: AddressControllerCallbacks): void
  /** Loads saved addresses when the identity has an account (no-op for guests). */
  init(): Promise<void>
  setQuery(text: string): void
  selectSuggestion(suggestionId: string): Promise<MutationResult>
  selectSavedAddress(savedAddressId: string): MutationResult
  setMode(mode: AddressEntryMode): void
  setDraftField(field: AddressField, value: string): void
  submitManualAddress(): Promise<MutationResult>
  dispose(): void
}

const initialState = (): AddressControllerState => ({
  mode: 'search',
  query: '',
  searching: false,
  suggestions: [],
  searchDegraded: false,
  savedAddresses: [],
  loadingSaved: false,
  draft: emptyAddress(),
  issues: {},
  submitting: false,
  resolvingSuggestionId: null,
  selected: null,
  errorMessage: null,
})

export function createAddressController(options: AddressControllerOptions): AddressController {
  const { service, context, addressType } = options
  const debounceMs = options.debounceMs ?? 250
  const minQueryLength = options.minQueryLength ?? 3
  let callbacks: AddressControllerCallbacks = {
    onAddressSelected: options.onAddressSelected,
    onAddressChange: options.onAddressChange,
  }

  let state = initialState()
  const listeners = new Set<() => void>()
  let searchTimer: ReturnType<typeof setTimeout> | null = null
  let searchSeq = 0

  const setState = (patch: Partial<AddressControllerState>): void => {
    state = { ...state, ...patch }
    for (const listener of listeners) listener()
  }

  const commitSelection = (address: AddressDTO): void => {
    setState({ selected: address, draft: address, errorMessage: null })
    callbacks.onAddressSelected?.(address)
  }

  /** Deterministic fallback: a provider outage must never block checkout. */
  const degradeToManual = (errorMessage: string): void => {
    setState({ mode: 'manual', searchDegraded: true, searching: false, suggestions: [], errorMessage })
  }

  const runSearch = async (text: string): Promise<void> => {
    const seq = ++searchSeq
    setState({ searching: true })
    const result = await service.searchAddresses(context, { text, addressType })
    if (seq !== searchSeq) return
    if (result.status === 'error') {
      degradeToManual(result.errorMessage ?? 'Address search is unavailable — enter your address manually.')
      return
    }
    setState({ searching: false, suggestions: result.suggestions })
  }

  return {
    getState: () => state,

    subscribe(listener) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },

    setCallbacks(next) {
      callbacks = next
    },

    async init() {
      if (!context.identity.accountId) return
      setState({ loadingSaved: true })
      const result = await service.listSavedAddresses(context, { addressType })
      setState({
        loadingSaved: false,
        savedAddresses: result.status === 'success' ? result.addresses : [],
      })
    },

    setQuery(text) {
      setState({ query: text })
      if (searchTimer) clearTimeout(searchTimer)
      if (state.searchDegraded) return
      if (text.trim().length < minQueryLength) {
        searchSeq += 1
        setState({ suggestions: [], searching: false })
        return
      }
      searchTimer = setTimeout(() => {
        void runSearch(text.trim())
      }, debounceMs)
    },

    async selectSuggestion(suggestionId) {
      setState({ resolvingSuggestionId: suggestionId })
      const result = await service.resolveAddress(context, { suggestionId })
      setState({ resolvingSuggestionId: null })
      if (result.status === 'error' || !result.address) {
        const errorMessage = result.errorMessage ?? 'Could not load that address — enter it manually.'
        degradeToManual(errorMessage)
        return { status: 'error', errorMessage }
      }
      setState({ suggestions: [], query: '' })
      commitSelection(result.address)
      return { status: 'success' }
    },

    selectSavedAddress(savedAddressId) {
      const saved = state.savedAddresses.find((entry) => entry.id === savedAddressId)
      if (!saved) return { status: 'error', errorMessage: 'Saved address not found' }
      commitSelection(saved.address)
      return { status: 'success' }
    },

    setMode(mode) {
      setState({ mode, errorMessage: null })
    },

    setDraftField(field, value) {
      const draft = { ...state.draft, [field]: value }
      const issues = { ...state.issues }
      delete issues[field]
      setState({ draft, issues })
      callbacks.onAddressChange?.(draft)
    },

    async submitManualAddress() {
      const issues = validateAddressFormat(state.draft, addressType)
      if (Object.keys(issues).length > 0) {
        setState({ issues })
        return { status: 'error', errorMessage: 'Fix the highlighted fields' }
      }
      setState({ submitting: true, issues: {} })
      const result = await service.validateAddress(context, { address: state.draft, addressType })
      setState({ submitting: false })
      if (result.status === 'error') {
        // Validation outage never blocks checkout — the draft already passed format checks.
        commitSelection(normalizeAddress(state.draft))
        return { status: 'success' }
      }
      if (result.valid === false) {
        const errorMessage = result.errorMessage ?? 'This address could not be verified'
        setState({ issues: result.issues ?? {}, errorMessage })
        return { status: 'error', errorMessage }
      }
      commitSelection(result.normalized ?? normalizeAddress(state.draft))
      return { status: 'success' }
    },

    dispose() {
      if (searchTimer) clearTimeout(searchTimer)
    },
  }
}
